761	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
762		if prev.Kind != "auth_create" || prev.Params != sig {
763			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
764				ErrRequestConflict, prev.Operator, prev.RequestID)
765		}
766		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
767			Status: AuthActive, Replayed: true}
768		if prev.Rejected {
769			res.Err = codeErr(prev.Reason)
770			return res, res.Err
771		}
772		return res, nil
773	}
774	
775	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
776		b, _ := json.Marshal(struct {
777			Kind   string `json:"kind"`
778			AuthID string `json:"auth_id"`
779			Reason string `json:"reason"`
780		}{"auth_revoke", req.AuthID, req.Reason})
781		return string(b)
782	}
783	
784	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
785	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
786	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
787	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
788		missing := []string{}
789		if strings.TrimSpace(req.Operator) == "" {
790			missing = append(missing, "operator")
791		}
792		if strings.TrimSpace(req.Reason) == "" {
793			missing = append(missing, "reason")
794		}
795		if strings.TrimSpace(req.RequestID) == "" {
796			missing = append(missing, "request_id")
797		}
798		if strings.TrimSpace(req.AuthID) == "" {
799			missing = append(missing, "auth_id")
800		}
801		if len(missing) > 0 {
802			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
803				ErrInvalidArgument, strings.Join(missing, ", "))
804		}
805		r.mu.Lock()
806		defer r.mu.Unlock()
807		if err := r.checkOpen(); err != nil {
808			return RevokeAuthorizationResult{}, err
809		}
810	
811		now := r.now()
812		key := requestKey(req.Operator, req.RequestID)
813		sig := revokeAuthzParamsSig(req)
814		if prev, ok := r.state.Requests[key]; ok {
815			return r.replayRevokeAuthz(prev, sig)
816		}
817	
818		a, ok := r.state.Authzs[req.AuthID]
819		if !ok {
820			// 引用不存在不占用请求号。
821			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
822			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
823		}
824		if a.GranterID != req.Operator {
825			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
826				ErrForbidden, a.GranterID, req.AuthID)
827			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
828			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
829		}
830		switch authzCurrentStatus(a, now) {
831		case AuthUsed:
832			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
833			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
834			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
835		case AuthRevoked:
836			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
837			// 相同请求重放回放同一结果。
838			r.state.Requests[key] = request{
839				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
840				Params: sig, AuthID: req.AuthID,
841			}
842			if err := r.commit(); err != nil {
843				return RevokeAuthorizationResult{}, err
844			}
845			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
846		}
847	
848		from := AuthActive
849		if authzCurrentStatus(a, now) == AuthExpired {
850			from = AuthExpired
851		}
852		a.Status = "revoked"
853		a.RevokedAt = now
854		r.state.Authzs[req.AuthID] = a
855		authSeq := r.state.NextAuthSeq + 1
856		r.state.NextAuthSeq = authSeq
857		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
858			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
859			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
860			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
861		})
862		r.state.Requests[key] = request{
863			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
864			Params: sig, AuthID: req.AuthID,
865		}
866		if err := r.commit(); err != nil {
867			return RevokeAuthorizationResult{}, err
868		}
869		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
870	}
871	
872	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
873	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
874		r.state.Requests[key] = request{
875			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
876			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
877		}
878		_ = r.commit()
879	}
