1	package registry
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"strings"
7	)
8	
9	// ---- 整批发行 ----
10	
11	func (req IssueBatchRequest) validatePresent() error {
12		missing := []string{}
13		if strings.TrimSpace(req.Operator) == "" {
14			missing = append(missing, "operator")
15		}
16		if strings.TrimSpace(req.Reason) == "" {
17			missing = append(missing, "reason")
18		}
19		if strings.TrimSpace(req.RequestID) == "" {
20			missing = append(missing, "request_id")
21		}
22		if strings.TrimSpace(req.SeriesID) == "" {
23			missing = append(missing, "series_id")
24		}
25		if strings.TrimSpace(req.BatchNo) == "" {
26			missing = append(missing, "batch_no")
27		}
28		if len(missing) > 0 {
29			return fmt.Errorf("%w: 整批发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
30		}
31		if len(req.Entries) == 0 {
32			return fmt.Errorf("%w: 整批发行清单不能为空", ErrInvalidArgument)
33		}
34		seen := make(map[string]bool, len(req.Entries))
35		for i, e := range req.Entries {
36			if strings.TrimSpace(e.ItemID) == "" {
37				return fmt.Errorf("%w: 清单第 %d 条缺少藏品编号", ErrInvalidArgument, i+1)
38			}
39			if strings.TrimSpace(e.HolderID) == "" {
40				return fmt.Errorf("%w: 清单第 %d 条（藏品 %s）缺少初始持有人", ErrInvalidArgument, i+1, e.ItemID)
41			}
42			if seen[e.ItemID] {
43				return fmt.Errorf("%w: 清单内藏品编号 %s 重复", ErrInvalidArgument, e.ItemID)
44			}
45			seen[e.ItemID] = true
46		}
47		return nil
48	}
49	
50	func issueBatchParamsSig(req IssueBatchRequest) string {
51		// 条目按提交顺序进入签名：改动任一条目内容或条目顺序都会得到不同
52		// 签名，按请求号冲突拒绝。
53		type entry struct {
54			ItemID   string `json:"item_id"`
55			Metadata string `json:"metadata"`
56			HolderID string `json:"holder_id"`
57		}
58		entries := make([]entry, 0, len(req.Entries))
59		for _, e := range req.Entries {
60			entries = append(entries, entry{e.ItemID, e.Metadata, e.HolderID})
61		}
62		b, _ := json.Marshal(struct {
63			Kind     string  `json:"kind"`
64			SeriesID string  `json:"series_id"`
65			BatchNo  string  `json:"batch_no"`
66			Reason   string  `json:"reason"`
67			Entries  []entry `json:"entries"`
68		}{"issue_batch", req.SeriesID, req.BatchNo, req.Reason, entries})
69		return string(b)
70	}
71	
72	// IssueBatch 由系列创建账户一次提交同一系列、同一批次号下的多件藏品，
73	// 整批共用操作者、原因与请求号。成功后按提交顺序依次为每件建立登记、
74	// 初始持有（版本 1）与发行历史，历史序号连续递增，整批记录之间不会插入
75	// 其他发行或转让；各件随后可通过现有查询读取，并按现有规则转让、创建
76	// 代转授权与计算版税。整批成功同样固定系列的版税规则。
77	//
78	// 空清单、清单内编号重复或必填内容缺失按参数错误拒绝（文字元数据仍可
79	// 为空）；操作者、系列或任一初始持有人未登记按对象不存在拒绝；非系列
80	// 创建账户、系列已封存、操作者或初始持有人停用、任一藏品编号已占用
81	// 沿用单件发行的对应业务拒绝。整批拒绝是原子的：不新增任何藏品、持有
82	// 或发行历史，尚未占用的编号仍可用于后续发行，系列版税规则也不会因此
83	// 固定。
84	//
85	// 请求号与单件发行、转让等操作共用同一操作者的请求号范围：内容与条目
86	// 顺序相同的重复提交回放整批首次结果（成功或状态类业务拒绝）并标明
87	// Replayed；改动原因、系列、批次号、条目顺序或任一条目内容返回
88	// ErrRequestConflict。成功回放仍给出最初的发行结果，即使藏品已转走、
89	// 系列已封存或账户已停用。参数错误与引用不存在不占用请求号，修正后可
90	// 用原号重新提交。
91	func (r *Registry) IssueBatch(req IssueBatchRequest) (IssueBatchResult, error) {
92		if err := req.validatePresent(); err != nil {
93			return IssueBatchResult{}, err
94		}
95		r.mu.Lock()
96		defer r.mu.Unlock()
97		if err := r.checkOpen(); err != nil {
98			return IssueBatchResult{}, err
99		}
100	
101		key := requestKey(req.Operator, req.RequestID)
102		sig := issueBatchParamsSig(req)
103		if prev, ok := r.state.Requests[key]; ok {
104			return r.replayIssueBatch(prev, sig)
105		}
106	
107		itemID, bizErr := r.checkIssueBatch(req)
108		if bizErr != nil {
109			if !isValidationErr(bizErr) {
110				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
111				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
112				r.state.Requests[key] = request{
113					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue_batch",
114					Params: sig, Rejected: true, Reason: errCode(bizErr),
115					ItemID: itemID,
116				}
117				_ = r.commit()
118			}
119			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
120			return IssueBatchResult{ItemID: itemID, Err: bizErr}, bizErr
121		}
122	
123		// 在同一临界区内依次为每件建立登记、持有与发行历史，序号连续递增；
124		// 与其他操作互斥，整批记录之间不会插入其他发行或转让。
125		items := make([]IssueBatchItem, 0, len(req.Entries))
126		stored := make([]batchItemResult, 0, len(req.Entries))
127		for _, e := range req.Entries {
128			seq := r.state.NextSeq + 1
129			r.state.NextSeq = seq
130			r.state.Items[e.ItemID] = item{
131				ID: e.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
132				Metadata: e.Metadata, IssuedTxID: seq,
133			}
134			r.state.Holdings[e.ItemID] = holding{ItemID: e.ItemID, OwnerID: e.HolderID, Version: 1}
135			r.state.History = append(r.state.History, historyEntry{
136				Seq: seq, Kind: "issue", ItemID: e.ItemID, Operator: req.Operator,
137				Reason: req.Reason, RequestID: req.RequestID,
138				FromID: "", ToID: e.HolderID, FromVersion: 0, ToVersion: 1,
139			})
140			items = append(items, IssueBatchItem{ItemID: e.ItemID, OwnerID: e.HolderID, Version: 1, TxSeq: seq})
141			stored = append(stored, batchItemResult{ItemID: e.ItemID, OwnerID: e.HolderID, TxSeq: seq})
142		}
143		r.state.Requests[key] = request{
144			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue_batch",
145			Params: sig, Batch: stored,
146		}
147		if err := r.commit(); err != nil {
148			return IssueBatchResult{}, err
149		}
150		return IssueBatchResult{Items: items}, nil
151	}
152	
153	// checkIssueBatch 校验整批发行。返回业务拒绝所涉及的藏品编号（与具体
154	// 某件无关时为空）与错误本身；任何一件不通过则整批拒绝。
155	func (r *Registry) checkIssueBatch(req IssueBatchRequest) (string, error) {
156		op, ok := r.state.Accounts[req.Operator]
157		if !ok {
158			return "", fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
159		}
160		if !op.Active {
161			return "", fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
162		}
163		s, ok := r.state.Series[req.SeriesID]
164		if !ok {
165			return "", fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
166		}
167		if s.Sealed {
168			return "", fmt.Errorf("%w: 系列 %s", ErrSeriesSealed, req.SeriesID)
169		}
170		if s.CreatorID != req.Operator {
171			return "", fmt.Errorf("%w: 只有系列创建账户 %s 可以发行", ErrForbidden, s.CreatorID)
172		}
173		for _, e := range req.Entries {
174			if _, ok := r.state.Items[e.ItemID]; ok {
175				return e.ItemID, fmt.Errorf("%w: 藏品编号 %s 已被使用", ErrAlreadyExists, e.ItemID)
176			}
177		}
178		for _, e := range req.Entries {
179			h, ok := r.state.Accounts[e.HolderID]
180			if !ok {
181				return e.ItemID, fmt.Errorf("%w: 初始持有人账户 %s", ErrNotFound, e.HolderID)
182			}
183			if !h.Active {
184				return e.ItemID, fmt.Errorf("%w: 初始持有人账户 %s", ErrAccountInactive, e.HolderID)
185			}
186		}
187		return "", nil
188	}
189	
190	func (r *Registry) replayIssueBatch(prev request, sig string) (IssueBatchResult, error) {
191		if prev.Kind != "issue_batch" || prev.Params != sig {
192			return IssueBatchResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
193				ErrRequestConflict, prev.Operator, prev.RequestID)
194		}
195		res := IssueBatchResult{ItemID: prev.ItemID, Replayed: true}
196		if prev.Rejected {
197			res.Err = codeErr(prev.Reason)
198			return res, res.Err
199		}
200		// 回放整批首次成功的发行结果：即使藏品后来已转走、系列已封存或账户
201		// 已停用，仍返回最初的持有人与历史序号，不改写当前状态。
202		for _, bi := range prev.Batch {
203			res.Items = append(res.Items, IssueBatchItem{
204				ItemID: bi.ItemID, OwnerID: bi.OwnerID, Version: 1, TxSeq: bi.TxSeq,
205			})
206		}
207		return res, nil
208	}
