	// 改内容 -> 请求号冲突
	reqChange := req
	reqChange.Shares = []IntentionShare{
		{AccountID: "alice", Rate: 4000},
		{AccountID: "bob", Rate: 4000},
		{AccountID: "carol", Rate: 2000},
