func TestCreateIntentionStatusConflict(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	intentionWorld(t, r)

	// 第一份意向有效（待确认）
	req := createIntentionReq(r, "i1-a", time.Hour, defaultShares())
	if _, err := r.CreateIntention(req); err != nil {
